/**
 * Self-learning loop telemetry for agent-mode tool calls.
 *
 * Emits one decision event + per-tool invoked/succeeded/failed events into the
 * shared LoopEvents table. Fire-and-forget: never awaited on the chat hot path,
 * and a no-op unless AGENT_RUNTIME_SPINE_ENABLED=true (or the legacy
 * AGENT_MODE_LOOP_ENABLED=true) because getAgentRunRecorder returns null.
 *
 * Keep V0 observability-only: this must not change tool execution, retries,
 * prompts, streaming, or user-facing responses.
 */
export function recordAgentModeToolTelemetry(
  runId: string,
  sessionId: string,
  iteration: number,
  toolResults: Array<{ status: 'success' | 'error' | 'deferred'; toolCall: any; functionArgs?: any; result?: any; error?: any; duration: number; policyDecision?: AgentToolPolicyDecision }>,
  budgetContext?: { mediaAssetsProducedThisRun?: number; mediaGenerationDeadlineMs?: number },
  userId?: string,
): void {
  // ENG-1907: sandbox runs write no reliability telemetry (see agentMode/sandboxTelemetry.ts).
  if (isSandboxRun(runId, userId)) return;
  const recorder = getAgentRunRecorderSafe();
  if (!recorder || toolResults.length === 0) return;

  // ENG-102: enqueue the per-tool records SYNCHRONOUSLY (no detached `void
  // (async)` wrapper). The recorder's internal write chain serializes them in
  // call order, so they always precede the terminal run record enqueued after
  // the loop — and the terminal record's flush implies these are durably
  // written before the worker exits. Still non-blocking from the caller's view:
  // the recorder methods return immediately and the chain settles in the
  // background (drained at run end). Only the synchronous summary computation is
  // wrapped in try/catch — telemetry must never break the chat hot path.
  try {
    const toolNames = toolResults.map(r => r.toolCall?.function?.name ?? 'unknown');
    // PR #1818 follow-up: contract-layer activity as countable telemetry so
    // the enforcement decision has data (args_repaired / schema-error rates).
    const argsRepairedCount = toolResults.filter(
      (r) => r.policyDecision?.flags?.some((flag) => flag.code === 'args_repaired'),
    ).length;
    const schemaErrorCount = toolResults.filter(
      (r) => r.status === 'error' && classifyToolErrorClass(r.error) === 'invalid_args',
    ).length;
    void recorder.decision(runId, {
      iteration,
      toolNames,
      sessionId,
      toolArgKeys: summarizeToolArgKeys(toolResults),
      toolArgsPreview: summarizeToolArgs(toolResults),
      decisionExplanation: summarizeToolDecision(toolResults),
      explanationSource: 'deterministic_tool_summary',
      toolPolicyFlags: summarizeAgentToolPolicyFlags(toolResults.map((r) => r.policyDecision)),
      toolPolicySummary: summarizeAgentToolPolicyModes(toolResults.map((r) => r.policyDecision)),
      argsRepairedCount,
      schemaErrorCount,
    });
    for (const r of toolResults) {
      const toolName = r.toolCall?.function?.name ?? 'unknown';
      if (r.status === 'deferred') {
        // ENG-103: a deferred call never executed → record it as its own class,
        // NOT as toolInvoked (keeps the reliability denominator clean) and NOT
        // as a failure (it carries no error signal).
        void recorder.toolDeferred(runId, {
          toolName,
          // A handler-supplied deferral names its own reason (ENG-822); the
          // media-budget path keeps the original default.
          reason: (r.result as any)?.reason || 'media_generation_time_budget',
          iteration,
          sessionId,
          ...(budgetContext?.mediaAssetsProducedThisRun != null
            ? { mediaAssetsProducedThisRun: budgetContext.mediaAssetsProducedThisRun }
            : {}),
          ...(budgetContext?.mediaGenerationDeadlineMs != null
            ? { deadlineMs: budgetContext.mediaGenerationDeadlineMs }
            : {}),
        });
        continue;
      }
      void recorder.toolInvoked(runId, { toolName, iteration, sessionId });
      if (r.status === 'success') {
        void recorder.toolSucceeded(runId, { toolName, durationMs: r.duration, sessionId });
        // ENG-104: a success that returned an explicitly partial result (e.g.
        // get_meta_ads_metrics with an errored breakdown section) is still a
        // success, but its degradation is recorded as its own class so a section
        // silently going dark is visible in telemetry instead of hiding behind
        // success:true. Emitted only when the result is flagged partialFailure —
        // the all-success path emits nothing (behavior-preserving).
        const partial = buildToolPartialFailureTelemetry(toolName, r.result);
        if (partial) {
          void recorder.toolPartialFailure(runId, {
            toolName: partial.toolName,
            unavailableSections: partial.unavailableSections,
            iteration,
            sessionId,
          });
        }
      } else {
        void recorder.toolFailed(runId, { toolName, error: r.error, durationMs: r.duration, sessionId, args: r.functionArgs });
      }
    }
  } catch (err) {
    console.error('[agent-mode] tool telemetry failed (swallowed):', err);
  }
}


export function recordAgentModeRunStarted(
  runId: string,
  info: { llmModel?: string; sessionType?: string; userId?: string; sessionId?: string },
): void {
  // OTel spine (ENG-141): the invoke_agent span opens here and closes in
  // recordAgentModeRunCompleted/Failed — the run-telemetry lifecycle exactly.
  // The traceId is bridged into the recorder's agent_run_started dimensions so
  // Dev-AW-LoopEvents rows can be joined to Langfuse/Okareo traces by ID.
  startInvokeAgentSpan(runId, info);
  if (isEvaluationUser(info.userId)) {
    markSandboxRun(runId);
    return;
  }
  forgetSandboxRun(runId);
  const recorder = getAgentRunRecorderSafe();
  if (!recorder) return;
  const traceId = getRunTraceId(runId);
  void recorder.runStarted(runId, traceId ? { ...info, traceId } : info);
}

export function recordAgentModeRunCompleted(
  runId: string,
  info: RunTerminalInfo,
  userId?: string,
): void {
  endInvokeAgentSpan(runId, {
    verdict: computeRunVerdict({
      failed: false,
      toolCalls: info.toolCalls ?? 0,
      failedToolCalls: info.failedToolCalls ?? 0,
      maxSameToolFailures: info.maxSameToolFailures,
    }).verdict,
    responseModel: info.llmModel,
  });
  if (releaseSandboxRun(runId, userId)) return;
  const recorder = getAgentRunRecorderSafe();
  if (!recorder) return;
  void recorder.runCompleted(runId, info);
}

/**
 * The finalize guard's claim check itself failed (judge/correction LLM call
 * errored, ENG-143). LOUD by contract: the guard delivers the chat unchanged on
 * judge failure — this signal (console + durable agent_claim_check_error event)
 * is the only trace that a truthfulness check was skipped. Best-effort: must
 * never throw into the chat hot path.
 */
export function recordAgentModeClaimCheckError(runId: string, sessionId: string, error: unknown, userId?: string): void {
  console.error('[agent-mode] finalize-guard claim check FAILED (message delivered unchanged):', {
    runId,
    sessionId,
    error: error instanceof Error ? error.message : String(error),
  });
  if (isSandboxRun(runId, userId)) return;
  const recorder = getAgentRunRecorderSafe();
  if (!recorder) return;
  void recorder.claimCheckError(runId, { error, sessionId });
}

export function recordAgentModeRunFailed(
  runId: string,
  info: RunTerminalInfo & { error: unknown },
  userId?: string,
): void {
  endInvokeAgentSpan(runId, { verdict: 'failed', error: info.error, responseModel: info.llmModel });
  if (releaseSandboxRun(runId, userId)) return;
  const recorder = getAgentRunRecorderSafe();
  if (!recorder) return;
  void recorder.runFailed(runId, info);
}

/**
 * Record same-turn duplicate tool-call suppression (ENG-108) as a structured,
 * observability-only signal — SEPARATE from success/failure telemetry (a
 * suppressed duplicate is neither). Best-effort: never throws into the chat hot
 * path.
 */
function recordAgentModeDuplicateSuppression(
  runId: string,
  sessionId: string,
  iteration: number,
  entries: Array<{ toolCall: any; functionArgs: any; duplicateOfId: string }>,
): void {
  if (entries.length === 0) return;
  try {
    for (const entry of entries) {
      console.warn('[agent-mode] duplicate tool call suppressed', {
        runId,
        sessionId,
        iteration,
        toolName: entry.toolCall?.function?.name ?? 'unknown',
        duplicateOfId: entry.duplicateOfId,
      });
    }
  } catch (err) {
    console.error('[agent-mode] duplicate-suppression telemetry failed (swallowed):', err);
  }
}

/**
 * Record a model fallback (ENG-46) as a structured, greppable, observability-only
 * signal. When a request pins a model id that is no longer served (e.g. a stale
 * post-deploy smoke-test config or a retired DB default), `resolveGenerationModel`
 * substitutes the default so the request still completes — but that substitution
 * MUST be visible to ops, not silently buried, otherwise a stale config keeps
 * shipping the wrong model unnoticed. The stable `[agent-mode] model fallback`
 * tag is what log dashboards/alerts key on. Best-effort: never throws into the
 * chat hot path.
 */
function recordAgentModeModelFallback(
  runId: string,
  sessionId: string,
  requestedModel: string,
  resolvedModel: string,
): void {
  try {
    console.warn('[agent-mode] model fallback', {
      runId,
      sessionId,
      requestedModel: requestedModel || '(none)',
      resolvedModel,
    });
  } catch (err) {
    console.error('[agent-mode] model-fallback telemetry failed (swallowed):', err);
  }
}

function countFailedToolCalls(toolCalls: any[]): number {
  return toolCalls.filter((toolCall) => toolCall && 'error' in toolCall).length;
}

/** Highest per-tool failure count — feeds the retry-spiral degraded-run rule. */
function maxSameToolFailureCount(toolCalls: any[]): number {
  const counts = new Map<string, number>();
  for (const toolCall of toolCalls) {
    if (!toolCall || !('error' in toolCall)) continue;
    const name = toolCall.name ?? 'unknown';
    counts.set(name, (counts.get(name) ?? 0) + 1);
  }
  return counts.size > 0 ? Math.max(...counts.values()) : 0;
}

const AGENT_RUNTIME_ARG_PREVIEW_MAX_CHARS = 1200;
const AGENT_RUNTIME_REDACTED_ARG_KEYS = /token|secret|password|credential|authorization|api[_-]?key|cookie/i;

function summarizeToolArgKeys(
  toolResults: Array<{ toolCall: any; functionArgs?: any }>,
): string {
  return toolResults
    .map((r) => {
      const toolName = r.toolCall?.function?.name ?? 'unknown';
      const keys = r.functionArgs && typeof r.functionArgs === 'object' && !Array.isArray(r.functionArgs)
        ? Object.keys(r.functionArgs).sort().join('|')
        : '';
      return keys ? `${toolName}:${keys}` : `${toolName}:`;
    })
    .join(',');
}

function summarizeToolArgs(
  toolResults: Array<{ toolCall: any; functionArgs?: any }>,
): string {
  const safe = toolResults.map((r) => ({
    tool: r.toolCall?.function?.name ?? 'unknown',
    args: redactTelemetryValue(r.functionArgs),
  }));
  const json = JSON.stringify(safe);
  return json.length > AGENT_RUNTIME_ARG_PREVIEW_MAX_CHARS
    ? `${json.slice(0, AGENT_RUNTIME_ARG_PREVIEW_MAX_CHARS - 3)}...`
    : json;
}

function summarizeToolDecision(
  toolResults: Array<{ toolCall: any; functionArgs?: any }>,
): string {
  const toolNames = toolResults.map((r) => r.toolCall?.function?.name ?? 'unknown');
  const uniqueTools = [...new Set(toolNames)];
  if (uniqueTools.length === 0) return 'No tool decision was recorded.';
  if (uniqueTools.every((name) => name === 'you_search_web')) {
    const queries = toolResults
      .map((r) => typeof r.functionArgs?.query === 'string' ? r.functionArgs.query : '')
      .filter(Boolean)
      .slice(0, 3);
    return queries.length > 0
      ? `Chose web search to gather external or current information for: ${queries.join(' | ')}.`
      : 'Chose web search to gather external or current information.';
  }
  const reasons: string[] = [];
  if (uniqueTools.includes('save_memory')) reasons.push('save_memory to persist user-provided information for future context');
  if (uniqueTools.includes('read_file_content')) reasons.push('read_file_content to inspect a file artifact before answering');
  if (uniqueTools.includes('save_file')) reasons.push('save_file to create or update a durable file artifact');
  if (uniqueTools.includes('install_skills')) reasons.push('install_skills to make a required skill or work-plan capability available before continuing');
  if (reasons.length === 1 && uniqueTools.length === 1) return `Chose ${reasons[0]}.`;
  if (reasons.length > 0) return `Chose multiple tools: ${reasons.join('; ')}.`;
  if (uniqueTools.some((name) => name.startsWith('playwright_browser_'))) {
    return `Chose browser automation to inspect or interact with a webpage using: ${uniqueTools.join(', ')}.`;
  }
  if (uniqueTools.includes('create_task_from_prompt')) {
    return 'Chose create_task_from_prompt because the request appears to require creating a tracked task.';
  }
  if (uniqueTools.length === 1) {
    return `Chose ${uniqueTools[0]} based on the requested action and available tool schema.`;
  }
  return `Chose multiple tools in one iteration: ${uniqueTools.join(', ')}.`;
}

function redactTelemetryValue(value: unknown, depth = 0): unknown {
  if (depth > 3) return '[truncated]';
  if (value === null || value === undefined) return value ?? null;
  if (typeof value === 'string') {
    return value.length > 240 ? `${value.slice(0, 237)}...` : value;
  }
  if (typeof value === 'number' || typeof value === 'boolean') return value;
  if (Array.isArray(value)) {
    return value.slice(0, 8).map((item) => redactTelemetryValue(item, depth + 1));
  }
  if (typeof value === 'object') {
    const out: Record<string, unknown> = {};
    for (const [key, child] of Object.entries(value as Record<string, unknown>).slice(0, 24)) {
      out[key] = AGENT_RUNTIME_REDACTED_ARG_KEYS.test(key)
        ? '[redacted]'
        : redactTelemetryValue(child, depth + 1);
    }
    return out;
  }
  return String(value);
}

function getAgentRunRecorderSafe() {
  try {
    return getAgentRunRecorder();
  } catch (err) {
    console.error('[agent-mode] runtime spine recorder unavailable (swallowed):', err);
    return null;
  }
}

/**
 * Drain the recorder's pending writes before worker/IPC teardown (ENG-102) so
 * per-tool + terminal telemetry are durably written before the worker process
 * exits — bounded by a timeout (mirroring the 5s generateSuggestedReplies guard)
 * so it can never hang the response. No-op when the runtime spine is disabled.
 */
async function flushAgentRunRecorderSafe(timeoutMs = 5000): Promise<void> {
  const recorder = getAgentRunRecorderSafe();
  if (!recorder) return;
  try {
    await Promise.race([
      recorder.flush(),
      new Promise<void>((resolve) => setTimeout(resolve, timeoutMs)),
    ]);
  } catch {
    // best-effort — telemetry drain must never break the chat turn
  }
}

function buildAgentRuntimeRunId(sessionId: string): string {
  const randomSuffix = Math.random().toString(36).slice(2, 8);
  return `${sessionId}:run:${Date.now().toString(36)}:${randomSuffix}`;
}

