export type { ModelTier, ModelProvider } from './agentMode/llmModelRegistry';

export { TIER_COST_SCORE_BANDS, QUALITY_SCORE_BANDS, tierFromCostScore, tierFromQualityScore } from './agentMode/modelClassification';
export { deriveDominanceLegacyIds } from './agentMode/modelSupersession';
export type { DominanceCandidate } from './agentMode/modelSupersession';

/** Metadata for a model as returned to the frontend picker. */
export interface SupportedModelInfo {
  id: string;
  name: string;
  /** Cost tier — derived from costScore via tierFromCostScore (see TIER_COST_SCORE_BANDS). */
  tier: ModelTier;
  /**
   * Quality tier — derived from qualityScore via tierFromQualityScore (see
   * QUALITY_SCORE_BANDS). Independent axis from `tier`: a model can be
   * Flagship on quality but Pro on cost, or vice versa. Omitted when
   * qualityScore itself is omitted (no benchmark evidence).
   */
  qualityTier?: ModelTier;
  description: string;
  provider: ModelProvider;
  /** True for a superseded version the picker should tuck behind "Show more". Omitted (not `false`) for a current/primary model. */
  legacy?: true;
  /** 0-100, higher = stronger. Omitted when there's no benchmark evidence — never a guess. */
  qualityScore?: number;
  qualityScoreSource?: string;
  /** 0-100, higher = more expensive. Omitted when pricing isn't available. */
  costScore?: number;
  costScoreSource?: string;
}


// Type for LLM call options
/**
 * Bedrock's default prompt-cache TTL. A prefix re-read inside this window is a
 * free refresh; only a gap longer than it can justify the 1-hour rate (ENG-893).
 */
const PROMPT_CACHE_DEFAULT_TTL_MS = 5 * 60 * 1000;

interface LLMCallOptions {
  /** ENG-2108: set only by the agent's own working loop; lets this call use a customer key. */
  customerRoutable?: boolean;
  tools?: any[] | null;
  /** ENG-2824: tool names that must survive maxTools truncation (e.g. a schedule's required calls). */
  priorityToolNames?: string[];
  tool_choice?: 'auto' | 'none' | any | null;
  /** Execute search through OpenRouter's provider-independent server tool. */
  webSearch?: boolean;
  /** Parameters for the web-search server tool (engine, max_results, max_uses, ...); omitted means OpenRouter's defaults. */
  webSearchParameters?: Record<string, string | number>;
  max_completion_tokens?: number | null;
  temperature?: number | null;
  response_format?: { type: 'text' | 'json_object' } | null;
  /**
   * Optional attribution for shadow usage metering (Ship 1). Recording is
   * fire-and-forget and fail-open — it never changes the call's behavior.
   * When omitted, usage is recorded under userId "system".
   */
  usageContext?: LLMUsageContext | null;
  /**
   * ENG-893: opt IN to the 1-hour prompt-cache TTL, for conversations with human
   * thinking time between turns.
   *
   * The default is deliberately OFF. A 1-hour cache write costs 2x input where a
   * 5-minute write costs 1.25x, and a cache HIT refreshes the TTL for free — so
   * the extended TTL only pays for itself when turns are far enough apart to have
   * expired the 5-minute window. Machine-paced callers (scheduled runs, loops,
   * one-shot judges and utility calls) fire back-to-back or never re-read the
   * prefix at all, so for them it is a pure surcharge. Opting in rather than out
   * means a new call site that has not thought about pacing keeps today's
   * behaviour instead of silently buying the 2x rate.
   */
  humanPaced?: boolean;
  /** Stable product taxonomy used by the reversible OpenRouter cutover canary. */
  taskClass?: GatewayTaskClass;
  /** Per-request transport deadline for bounded background and judge calls. */
  timeoutMs?: number;
  /** Ordered logical model fallbacks executed by OpenRouter, never by AgentWeb. */
  fallbackModels?: string[];
  /**
   * ENG-55: Compare-only OpenRouter provider policy (`data_collection: 'deny'`), merged into
   * `provider` next to the shared order/fallback preferences. Normal chat never sets it.
   */
  providerPolicy?: CompareProviderPolicy | null;
  /** Provider names OpenRouter must not route this request to; merged with any default ignore list. */
  providerIgnore?: string[];
  /** Treat a 200 with no answer as a failed, retryable attempt. For callers that need text back. */
  requireContent?: boolean;
}

function nonNegativeTokenCount(value: unknown): number {
  return typeof value === 'number' && Number.isFinite(value)
    ? Math.max(0, Math.round(value))
    : 0;
}

/**
 * Convert an OpenAI-compatible usage object into the ledger's disjoint token
 * dimensions. OpenRouter follows OpenAI's contract: `prompt_tokens` includes
 * cache reads/writes and `prompt_tokens_details` identifies those subsets. Our
 * ledger prices uncached input, cache reads, and cache writes separately, so
 * forwarding the inclusive prompt total double-counts the cached portion.
 *
 * Provider-native Bedrock/Vertex adapters already report uncached input and
 * cache reads as disjoint counters; their existing semantics stay unchanged.
 * External counters are finite/non-negative and the OpenRouter cache subset is
 * bounded by its prompt total so malformed provider data cannot inflate usage.
 */
function normalizeCallUsageTokens(usage: any, provider: string): {
  inputTokens: number;
  outputTokens: number;
  cacheReadTokens: number;
  cacheWriteTokens: number;
} {
  const promptTokens = nonNegativeTokenCount(usage?.prompt_tokens);
  const outputTokens = nonNegativeTokenCount(usage?.completion_tokens);
  const providerCacheReadTokens = nonNegativeTokenCount(usage?.cache_read_input_tokens);
  const openAiCacheReadTokens = nonNegativeTokenCount(usage?.prompt_tokens_details?.cached_tokens);
  const reportedCacheReadTokens = providerCacheReadTokens || openAiCacheReadTokens;
  const providerCacheWriteTokens = nonNegativeTokenCount(usage?.cache_creation_input_tokens);
  const openAiCacheWriteTokens = nonNegativeTokenCount(usage?.prompt_tokens_details?.cache_write_tokens);

  if (provider !== 'openrouter') {
    return {
      inputTokens: promptTokens,
      outputTokens,
      cacheReadTokens: reportedCacheReadTokens,
      cacheWriteTokens: providerCacheWriteTokens,
    };
  }

  const cacheReadTokens = Math.min(promptTokens, reportedCacheReadTokens);
  const remainingPromptTokens = promptTokens - cacheReadTokens;
  const reportedCacheWriteTokens = providerCacheWriteTokens || openAiCacheWriteTokens;
  const cacheWriteTokens = Math.min(remainingPromptTokens, reportedCacheWriteTokens);

  return {
    inputTokens: remainingPromptTokens - cacheWriteTokens,
    outputTokens,
    cacheReadTokens,
    cacheWriteTokens,
  };
}

