  /**
   * Search for Detailed Targeting options (Interests, Behaviors, Demographics)
   */
  public async searchAdTargeting(
    userId: string,
    account_id: string,
    q: string,
    type: string = 'adTargetingCategory',
    locationTypes?: string[]
  ): Promise<any> {
    try {
      const { accountId, accessToken } = await this.getMetaCredentials(userId, account_id);

      const searchResult = await metaService.searchTargeting(accountId, accessToken, q, type, locationTypes);
      const results = Array.isArray(searchResult) ? searchResult : [];

      return {
        success: true,
        message: `Found ${results.length} results for "${q}"`,
        data: results
      };
    } catch (error: any) {
      if (error.isMetaAuthError) throw error;
      console.error('AgentMode: Error searching ad targeting:', error);
      return {
        success: false,
        message: error.message || 'Failed to search ad targeting.',
        error: error.message,
        // ENG-1300: SDK-shaped error — never a Meta business code.
        code: error?.status ?? error?.response?.status
      };
    }
  }

  // ENG-2103 (F2): body moved verbatim to emma/impl/tasks.ts (non-contiguous
  // with the rest of this cluster — see that module's header comment). Kept
  // as a delegating wrapper: real caller beyond tools.ts is
  // routes/emmaApi.ts's POST /revision handler. [DEPRECATED] per
